body.usercss:

    .btn-css {
        position: absolute;
        height: 50px;
        background: white;
        right: 15px;
        z-index: 3;
    }

    /* 탭바 영역 CSS */

    .font-size-13 {
        font-size: 13px;
    }

    .font-size-14 {
        font-size: 14px;
    }

    .table-default-width {
        width: 100%;
        table-layout: fixed;
        border-collapse: collapse;
    }

    .table-td-subject {
        font-size: 13px;
        color: #797979;
        text-align: center;
    }

    .table-td-header {
        font-size: 13px;
        text-align: center;
    }

    .table-line1 {
        width: 70px;
        text-align: center;
    }

    .table-line2 {
        width: 45px;
        text-align: left;
        text-overflow: ellipsis;
		overflow: hidden;
		white-space: nowrap;
    }

    .table-line3 {
        width: 60px;
    }

    .table-line4 {
        width: 90px;
        padding: 3px;
    }

    .table-line4-align {
        text-align: center;
    }

    .table-line5 {
        width: 65px;
    }

    .table-line6 {
        width: 30px;
        vertical-align: initial;
        padding: 3px;
    }

    .detail-line {
        padding-top: 15px;
        padding-left: 4px;
    }

    /* 폼 영역 CSS */

    .form-table {
        width: 100%;
        margin-bottom: 10px;
        margin-top: 20px;
    }

    .form-subject {
        font-size: 14px;
        color: #222222;
    }

    .table-attach {
        margin-top: 15px;
    }

    .form-padding {
        padding-top: 15;
    }

    .custom-vertical {
        vertical-align: middle;
    }

    .text-area {
        width: 99%;
        resize: none;
        font-size: 12px;
        color: #222222;
        border-color: #d7d7d7;
        outline: #d7d7d7;
        padding: 5px;
    }

    .text-area-height {
        height: 20px;
    }

    .text-area-height-custom {
        height: 100px;
    }

    .text-area-margin {
        margin-top: 5px;
        margin-bottom: 10px;
    }

    .text-area-margin2 {
        margin-top: 5px;
    }

    .form-checkbox {
        font-size: 12px;
        margin-left: 10px;
    }

    .checkBox-margin {
        margin: 0;
    }

    .subject-margin {
        width: 100%;
        margin-top: 15px;
    }

    .hr-line {
    	width: 100%; 
    	height: 14px;
    	background-color: #f1f1f1;
    	border: 0;
    }

userscript.function:

config = data;

// 승인,반려 후 재호출시 reload플래그
if(config.reload){
	config.reload = true
} else{
	config.reload = false;
}

var smrNumber = config.SMR_NUMBER;
var appNo = config.APP_NO;
var appNoSeq = config.APP_NO_SEQ;

var params = {
    COMPANY_CODE: Sepoa.info.COMPANY_CODE,
    SMR_NUMBER: smrNumber,
    APP_NO: appNo,
    APP_NO_SEQ: appNoSeq,
    APPLY_TYPE: "D",
    SCREEN_TYPE: "M"
};

var appLineData = {};
var referenceLineData = {};
doServiceAjax('sepoa.svc.approval.SepoaApprovalService', 'CONNECTION', 'getAppLine', params, function(so) {
    if (so.status == 1) {
        sf = new SepoaFormater(so.result[0]);

        var appSize = 0;
        var referenceSize = 0;
        for (var i = 0; i < sf.getRowCount(); i++) {
            if (sf.dataMap.APP_METHOD[i] != '03') {
                appSize++
            } else {
                referenceSize++
            }
        }
        // 결재선 테이블
        for (var i = 0; i < sf.getRowCount(); i++) {
            var confirmUser;
            if (sf.dataMap.APP_METHOD[i] != '03') {
                appLineData.headerFlag = false;
                appLineData.endFlag = false;
                appLineData.detailFlag = false;

                if (i == 0) {
                    appLineData.headerFlag = true
                } else if (i == appSize - 1) {
                    appLineData.endFlag = true
                }

                if (sf.dataMap.ACCEPT_REASON[i] != '') {
                    appLineData.detailFlag = true;
                }

                var year = sf.dataMap.ACCEPT_DATE[i].substring(0, 4);
                var month = sf.dataMap.ACCEPT_DATE[i].substring(4, 6);
                var day = sf.dataMap.ACCEPT_DATE[i].substring(6, 8);
                var acceptDate = year + "/" + month + "/" + day;

                if (sf.dataMap.ACCEPT_DATE[i] == '') acceptDate = '';
                appLineData.APP_LINE_STATUS = sf.dataMap.APP_LINE_STATUS[i]
                appLineData.APP_METHOD = sf.dataMap.APP_METHOD[i]
                appLineData.APP_USER_ID = sf.dataMap.APP_USER_ID[i]
                appLineData.APP_USER_NAME = sf.dataMap.APP_USER_NAME[i]
                appLineData.APP_USER_DEPT_NAME = sf.dataMap.APP_USER_DEPT_NAME[i]
                appLineData.ACCEPT_DATE = acceptDate
                appLineData.ACCEPT_REASON = sf.dataMap.ACCEPT_REASON[i]
                appLineData.TABLE_ROW = i;
                appLineData.reload = config.reload

                // 결재대기자의 ID가 세션값과 다를경우 버튼숨김
                if (sf.dataMap.APP_LINE_STATUS[i] == 'L04') {
                    confirmUser = sf.dataMap.APP_USER_ID[i];
                    if (confirmUser != Sepoa.info.ID) {
                        btnObj.btn('confirm').setHide();
                        btnObj.btn('reject').setHide();
                    }
                }
                drawTabbarAppLine(appLineData)
            }

        }
        referenceHeaderDraw();
        for (var i = 0; i < sf.getRowCount(); i++) {
            if (sf.dataMap.APP_METHOD[i] == '03') {
                referenceLineData.headerFlag = false;
                referenceLineData.endFlag = false;
                referenceLineData.detailFlag = false;

                if (i == (sf.getRowCount() - referenceSize)) {
                    referenceLineData.headerFlag = true
                } else if (i == sf.getRowCount() - 1) {
                    referenceLineData.endFlag = true
                }

                referenceLineData.APP_LINE_STATUS = sf.dataMap.APP_LINE_STATUS[i]
                referenceLineData.APP_METHOD = sf.dataMap.APP_METHOD[i]
                referenceLineData.APP_USER_ID = sf.dataMap.APP_USER_ID[i]
                referenceLineData.APP_USER_NAME = sf.dataMap.APP_USER_NAME[i]
                referenceLineData.APP_USER_DEPT_NAME = sf.dataMap.APP_USER_DEPT_NAME[i]
                referenceLineData.ACCEPT_DATE = sf.dataMap.ACCEPT_DATE[i]
                referenceLineData.ACCEPT_REASON = sf.dataMap.ACCEPT_REASON[i]
                referenceLineData.TABLE_ROW = i;
                referenceLineData.reload = config.reload;

                drawTabbarReference(referenceLineData);
            }
        }
    }
});

if(!config.reload){
	getReqSealInfo(config, params);
}


		doServiceAjax('sepoa.svc.seal.SepoaReqSealService', 'CONNECTION', 'doSelectRequestInfo', params, function(so) {
        if (so.status == 1) {
            var reqData = JSON.parse(so.result[0]);
